// Cross-check: this user must also have an active partner agent config
const cfg = $json;
const partnerCheck = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://auth.purama.dev/rest/v1/partner_agent_config?user_id=eq.${cfg.user_id}&is_active=eq.true&select=user_id`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Accept-Profile': 'purama_ai',
  },
  json: true,
});
if (!partnerCheck.length) return [{ json: { ...cfg, _skip: true } }];

// Refresh access token if needed
let accessToken = cfg.gmail_access_token;
const expiry = cfg.gmail_token_expiry ? new Date(cfg.gmail_token_expiry).getTime() : 0;
if (!accessToken || expiry < Date.now() + 30000) {
  if (!cfg.gmail_refresh_token) return [{ json: { ...cfg, _skip: true } }];
  const r = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://oauth2.googleapis.com/token',
    body: new URLSearchParams({
      client_id: $env.GOOGLE_CLIENT_ID,
      client_secret: $env.GOOGLE_CLIENT_SECRET,
      refresh_token: cfg.gmail_refresh_token,
      grant_type: 'refresh_token',
    }).toString(),
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    json: true,
  });
  accessToken = r.access_token;
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `https://auth.purama.dev/rest/v1/email_agent_config?user_id=eq.${cfg.user_id}`,
    headers: {
      apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
      Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
      'Content-Profile': 'purama_ai',
      'Content-Type': 'application/json',
      Prefer: 'return=minimal',
    },
    body: { gmail_access_token: accessToken, gmail_token_expiry: new Date(Date.now() + (r.expires_in - 60) * 1000).toISOString() },
  });
}

// Pull contacted prospects with email
const prospects = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://auth.purama.dev/rest/v1/partner_prospects?user_id=eq.${cfg.user_id}&status=in.(contacted,relance_1,relance_2,relance_3)&has_replied=eq.false&email=not.is.null&select=id,name,email,status,relance_count`,
  headers: {
    apikey: $env.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${$env.SUPABASE_SERVICE_ROLE_KEY}`,
    'Accept-Profile': 'purama_ai',
  },
  json: true,
});
if (!prospects.length) return [{ json: { ...cfg, _skip: true } }];

return prospects.map((p) => ({ json: { ...cfg, _accessToken: accessToken, _prospect: p } }));

const ctx = $('Prepare prospects').item.json;
const messages = $json.messages || [];
if (!messages.length) return [];
// Pull the latest message body
const msgRes = await this.helpers.httpRequest({
  method: 'GET',
  url: `https://gmail.googleapis.com/gmail/v1/users/me/messages/${messages[0].id}?format=full`,
  headers: { Authorization: `Bearer ${ctx._accessToken}` },
  json: true,
});
function findPart(parts, mime) {
  for (const p of parts || []) {
    if (p.mimeType === mime && p.body?.data) return p.body.data;
    if (p.parts) { const r = findPart(p.parts, mime); if (r) return r; }
  }
  return null;
}
let body = '';
if (msgRes.payload?.body?.data) body = msgRes.payload.body.data;
else body = findPart(msgRes.payload?.parts, 'text/plain') || findPart(msgRes.payload?.parts, 'text/html') || '';
if (body) body = Buffer.from(body.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
body = body.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').slice(0, 3000);
return [{ json: { ...ctx, _body: body, _gmail_msg_id: msgRes.id, _thread_id: msgRes.threadId } }];

