const ctx = $('Fetch body').item.json;
const raw = $json.content?.[0]?.text || '{}';
let a = { sentiment: 'neutre', intent: 'question', summary: '', suggested_action: 'reply_answer' };
try { const m = raw.match(/\{[\s\S]*\}/); a = { ...a, ...JSON.parse(m ? m[0] : raw) }; } catch(e) {}
let newStatus = ctx._prospect.status;
if (a.intent === 'interested') newStatus = 'interested';
else if (a.intent === 'not_interested' || a.intent === 'unsubscribe') newStatus = 'rejected';
return [{ json: { ...ctx, _analysis: a, _new_status: newStatus } }];
